package cn.iocoder.yudao.module.system.api.oauth2;import cn.iocoder.yudao.module.system.api.oauth2.dto.client.OAuth2ClientCreateReqDTO;import cn.iocoder.yudao.module.system.convert.oauth2.OAuth2ClientConvert;import cn.iocoder.yudao.module.system.service.oauth2.OAuth2ClientService;import org.springframework.stereotype.Service;import javax.annotation.Resource;/** * OAuth2.0 Client API 接口实现 * * @author zhusy * @since 2022/8/30 */@Servicepublic class OAuth2ClientApiImpl implements OAuth2ClientApi {    @Resource    private OAuth2ClientService oAuth2ClientService;    @Override    public Long createOAuth2Client(OAuth2ClientCreateReqDTO reqDTO) {        return oAuth2ClientService.createOAuth2Client(OAuth2ClientConvert.INSTANCE.convert(reqDTO));    }}